outputs = ['ghejjk', 'xvbzcvk', 'zw', 'yhvzjg', 'ifua']

print("Analyzing input/output pairs:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{i+1}. '{inp}' → '{outp}'")

# Let's see if we can find what replacements are needed
replacements_needed = []

# Look for character substitutions
for inp, outp in zip(inputs, outputs):
    print(f"\nComparing '{inp}' and '{outp}':")
    for j in range(max(len(inp), len(outp))):
        if j < len(inp) and j < len(outp):
            if inp[j] != outp[j]:
                print(f"  Position {j}: '{inp[j]}' → '{outp[j]}'")
        elif j < len(inp):
            print(f"  Position {j}: '{inp[j]}' (removed)")
        elif j < len(outp):
            print(f"  Position {j}: '{outp[j]}' (added)")

# Check for simple character replacements
char_changes = {}
for inp, outp in zip(inputs, outputs):
    min_len = min(len(inp), len(outp))
    for i in range(min_len):
        if inp[i] != outp[i]:
            char_changes[inp[i]] = outp[i]

print("\nCharacter changes:", char_changes)

